# Remnants of HTML entities that survive tokenization when a corpus file was
# stored escaped (Hebrew gershayim are &quot; in word/document.xml). The docx
# reader now unescapes before analysis, but .md/.txt corpus files can still
# arrive pre-escaped, and "quot" outranking every real word poisons the
# vocabulary steering the write skill reads off frequentTerms.
ENTITY_REMNANTS = {
    "quot",
    "amp",
    "apos",
    "nbsp",
    "lt",
    "gt",
    "ndash",
    "mdash",
    "rsquo",
    "lsquo",
    "rdquo",
    "ldquo",
}

STOPWORDS = HEBREW_STOPWORDS | ENGLISH_STOPWORDS | ENTITY_REMNANTS


def _normalize(word: str) -> str:
    return word if HEBREW_CHAR_RE.search(word) else word.lower()


def compute_frequent_terms(text: str, top_n: int, min_len: int) -> list[dict]:
    words = tokenize_words(text)
    normalized = [
        _normalize(w)
        for w in words
        if len(w) >= min_len and _normalize(w) not in STOPWORDS
    ]
    total = len(normalized)
    counts = Counter(normalized)
    results = []
    for term, count in counts.most_common(top_n):
        results.append(
            {
                "term": term,
                "count": count,
                "frequency": round(count / total, 5) if total else 0.0,
            }
        )
    return results
